insert into public.exercises (id, name, instructions, created_by) values
  ('be67d976-60ec-4d1b-943c-3ee0de534ffc', 'Bench Press', 'Allongé sur le dos, barre ou haltères au niveau de la poitrine, poussez la charge vers le haut jusqu''à extension des bras, puis redescendez lentement en contrôlant la charge jusqu''à toucher légèrement le buste.', null),
  ('5365af8c-3c09-402b-9bac-0526f0a7daa5', 'Incline Bench Press', 'Allongé sur un banc incliné, barre ou haltères au niveau de la poitrine haute, poussez la charge vers le haut jusqu''à extension des bras, puis redescendez lentement en contrôlant la charge jusqu''à toucher légèrement le buste.', null),
  ('3b918060-fe55-431c-9b0c-a681bb0f2616', 'Incline Dumbbell Press', 'Allongé sur un banc incliné, un haltère dans chaque main au niveau de la poitrine haute, poussez-les vers le haut jusqu''à extension des bras, puis redescendez lentement.', null),
  ('c58ec504-af16-481f-93b9-7ccfb10092a3', 'Dumbbell Bench Press', 'Allongé sur le dos, barre ou haltères au niveau de la poitrine, poussez la charge vers le haut jusqu''à extension des bras, puis redescendez lentement en contrôlant la charge jusqu''à toucher légèrement le buste.', null),
  ('a28951fa-bbc0-4981-82ea-284f685d44a0', 'Decline Bench Press', 'Allongé sur un banc en déclive, barre au niveau du bas de la poitrine, poussez la charge vers le haut jusqu''à extension des bras, puis redescendez lentement en contrôlant la charge jusqu''à toucher légèrement le buste.', null),
  ('266978ef-4608-4193-92b3-13aa3a355aa6', 'Machine Chest Press', 'Assis ou allongé face à la machine, poignées au niveau de la poitrine, poussez vers l''avant jusqu''à extension des bras puis revenez lentement.', null),
  ('2eebd453-1113-4099-8fa5-af5493599da8', 'Pec Deck', 'Assis face à la machine, avant-bras contre les appuis, rapprochez les bras devant la poitrine en gardant un léger coude fléchi, puis revenez lentement en étirant la poitrine.', null),
  ('54e0024d-f021-4bff-a8f9-7dbccd8a45ad', 'Cable Fly', 'Bras légèrement fléchis, ramenez les mains ou les poignées l''une vers l''autre devant la poitrine en un large arc de cercle, puis revenez lentement en laissant les bras s''écarter.', null),
  ('d28ceaf6-0ffa-4227-b9e3-2f440acbf998', 'Push-up', 'Mains sous les épaules, corps gainé et aligné des talons à la tête, fléchissez les coudes pour descendre la poitrine vers le sol puis repoussez jusqu''à extension des bras.', null),
  ('fad3b9a4-b74a-4949-a60b-264408dab97a', 'Weighted Push-up', 'Une charge posée sur le haut du dos, mains sous les épaules, fléchissez les coudes pour descendre la poitrine vers le sol puis repoussez jusqu''à extension des bras.', null),
  ('f8e64c23-e4b5-4fb3-b5e3-f1de8ca134d2', 'Overhead Press', 'Debout, charge au niveau des épaules, poussez-la vers le haut jusqu''à extension complète des bras au-dessus de la tête, puis redescendez lentement au niveau des épaules.', null),
  ('13ef348e-4024-44d1-ab21-26df38f147a5', 'Dumbbell Seated Shoulder Press', 'Assis, charge au niveau des épaules, poussez-la vers le haut jusqu''à extension complète des bras au-dessus de la tête, puis redescendez lentement au niveau des épaules.', null),
  ('e238de32-074d-4868-9e01-c44c2501ce7d', 'Arnold Press', 'Assis, haltères devant les épaules paumes tournées vers vous, poussez-les vers le haut en tournant les paumes vers l''avant jusqu''à extension des bras, puis inversez le mouvement en redescendant.', null),
  ('e614adb7-64ab-4a7d-ba44-d270d6c58553', 'Lateral Raise', 'Debout, un poids dans chaque main le long du corps, levez les bras sur les côtés jusqu''à hauteur d''épaule, coudes légèrement fléchis, puis redescendez lentement.', null),
  ('aa0ac4e9-58b2-4d75-89a5-d1ccd8934e94', 'Cable Lateral Raise', 'Debout, un poids dans chaque main le long du corps, levez les bras sur les côtés jusqu''à hauteur d''épaule, coudes légèrement fléchis, puis redescendez lentement.', null),
  ('0ed9ecce-3ebf-4e59-898d-39793b9e7aa5', 'Front Raise', 'Debout, poids devant les cuisses, levez un ou deux bras tendus devant vous jusqu''à hauteur d''épaule, puis redescendez lentement.', null),
  ('41330774-8b52-42d6-81f8-5a6b1ba4e58e', 'Rear Delt Fly', 'Buste penché en avant (ou assis face à la machine), bras légèrement fléchis, écartez les bras sur les côtés en resserrant les omoplates, puis revenez lentement.', null),
  ('9ad9a232-cc5b-42e7-b11b-67c5e39a63cf', 'Reverse Pec Deck', 'Buste penché en avant (ou assis face à la machine), bras légèrement fléchis, écartez les bras sur les côtés en resserrant les omoplates, puis revenez lentement.', null),
  ('8f50e843-0f04-4fb5-b7cc-93d3cf1f9d0a', 'Face Pull', 'Face à la poulie haute avec une corde, tirez vers le visage en écartant les mains et en resserrant les omoplates, coudes hauts, puis revenez lentement en contrôlant.', null),
  ('5a20fb00-f477-4585-a282-3c3ecdd39e6c', 'Upright Row', 'Debout, barre ou haltères devant les cuisses, tirez la charge verticalement le long du corps jusqu''à hauteur de poitrine, coudes hauts, puis redescendez lentement.', null),
  ('8ce5af7f-7e76-4028-96d2-08e60c46d3f3', 'Deadlift', 'Debout, barre au sol devant les tibias, dos droit, saisissez la barre puis redressez-vous en poussant dans le sol jusqu''à extension complète des hanches et des genoux, avant de redescendre avec contrôle.', null),
  ('b845cfa5-f2a1-4b66-9cff-e34b84eaf579', 'Romanian Deadlift', 'Debout, charge dans les mains, jambes presque tendues, penchez le buste vers l''avant en poussant les hanches vers l''arrière, dos droit, jusqu''à sentir l''étirement à l''arrière des cuisses, puis remontez.', null),
  ('a2f05029-b36a-4993-ad27-89d1d59c0846', 'Barbell Row', 'Buste penché en avant, dos droit, tirez la barre vers le bas de l''abdomen en resserrant les omoplates, coudes proches du corps, puis redescendez avec contrôle.', null),
  ('d45be57a-4f35-4e13-854b-543ebf613fd0', 'T-Bar Row', 'Buste penché en avant, dos droit, tirez la barre vers le bas de l''abdomen en resserrant les omoplates, coudes proches du corps, puis redescendez avec contrôle.', null),
  ('9786575b-5571-4da6-9c5a-4a2e1d4ef426', 'Dumbbell Bent Over Row', 'Buste penché en avant, dos droit, un haltère dans chaque main, tirez les coudes vers l''arrière en resserrant les omoplates, puis redescendez avec contrôle.', null),
  ('40323f87-ab58-497a-891f-e6f368213c11', 'One-Arm Dumbbell Row', 'Un genou et une main en appui, dos droit, tirez l''haltère ou la poignée vers la hanche en resserrant l''omoplate, puis redescendez avec contrôle.', null),
  ('c2c289b8-7e88-4de0-8efc-84abfc69156c', 'Chest Supported Row', 'Poitrine appuyée contre un banc incliné, tirez la charge vers l''abdomen en resserrant les omoplates, puis redescendez avec contrôle.', null),
  ('65f4251f-b9e2-4fa4-a2a8-7185d5f4dfcb', 'Seated Cable Row', 'Assis face à la poulie basse, jambes légèrement fléchies, tirez la poignée vers l''abdomen en gardant le dos droit et en resserrant les omoplates, puis revenez lentement.', null),
  ('123a34e7-7be6-417b-bd6e-ae2f0a91298f', 'Machine Row', 'Assis face à la machine, poitrine calée contre l''appui, tirez les poignées vers vous en resserrant les omoplates, puis revenez lentement.', null),
  ('ebac36c3-90e8-44a1-813a-c3160e41552a', 'Lat Pulldown', 'Assis face à la poulie haute, tirez la barre vers le haut de la poitrine en resserrant les omoplates, puis remontez avec contrôle jusqu''à extension des bras.', null),
  ('ebad889d-1036-440c-94b4-2dc3a989927a', 'Close-Grip Lat Pulldown', 'Assis face à la poulie haute, tirez la barre vers le haut de la poitrine en resserrant les omoplates, puis remontez avec contrôle jusqu''à extension des bras.', null),
  ('8bba1f78-8b20-4172-b0f5-1ebfdbae36e4', 'Straight-Arm Pulldown', 'Debout face à la poulie haute, bras tendus, tirez la barre vers les cuisses en gardant les bras tendus, puis remontez avec contrôle.', null),
  ('e4e2383f-1d78-4674-be04-df7d6e15f63e', 'Pull-up', 'Suspendu à une barre fixe, prise en pronation (paumes vers l''avant) tirez le corps vers le haut jusqu''à ce que le menton dépasse la barre, puis redescendez avec contrôle.', null),
  ('91c7c84d-2da6-4baa-aa43-912596b13860', 'Assisted Pull-up', 'Suspendu à une barre fixe, prise en pronation (paumes vers l''avant), à l''aide d''un élastique ou d''une machine d''assistance, tirez le corps vers le haut jusqu''à ce que le menton dépasse la barre, puis redescendez avec contrôle.', null),
  ('ec642c92-8649-425d-b1b6-2eabfc0924f4', 'Weighted Pull-up', 'Suspendu à une barre fixe, prise en pronation (paumes vers l''avant) tirez le corps vers le haut jusqu''à ce que le menton dépasse la barre avec une charge additionnelle, puis redescendez avec contrôle.', null),
  ('7afaf05d-41dd-4627-8403-e09bd97a9ff5', 'Chin-up', 'Suspendu à une barre fixe, prise en supination (paumes vers vous) tirez le corps vers le haut jusqu''à ce que le menton dépasse la barre, puis redescendez avec contrôle.', null),
  ('c7e7d34a-2580-44c5-9af8-365ff9ea8af3', 'Barbell Shrug', 'Debout, poids dans chaque main le long du corps, remontez les épaules vers les oreilles sans fléchir les coudes, maintenez brièvement, puis redescendez avec contrôle.', null),
  ('73878f59-d02d-4dd6-9050-2d75b9f0f265', 'Squat', 'Barre sur le haut du dos, pieds largeur d''épaules, descendez en fléchissant les hanches et les genoux jusqu''à ce que les cuisses soient parallèles au sol, dos droit, puis remontez en poussant dans les pieds.', null),
  ('5dc44244-014b-4918-9895-d4692a25cd38', 'Front Squat', 'Barre posée sur le haut de la poitrine, coudes hauts, descendez en fléchissant les hanches et les genoux jusqu''à ce que les cuisses soient parallèles au sol, dos droit, puis remontez.', null),
  ('062386cf-3c8b-4f07-8d54-df9033f6bcb4', 'Hack Squat', 'Dos calé contre le dossier incliné de la machine, pieds sur la plateforme, descendez en fléchissant les genoux jusqu''à un angle confortable, puis remontez en poussant dans les pieds.', null),
  ('1c5c6a92-410c-4f0b-8572-672c15505b8e', 'Leg Press', 'Assis, dos calé contre le dossier, pieds sur la plateforme largeur de hanches, fléchissez les genoux pour rapprocher la plateforme, puis repoussez sans verrouiller complètement les genoux.', null),
  ('81b73847-deb2-40ff-97a2-7a3ec1ca8c01', 'Bulgarian Split Squat', 'Pied arrière posé sur un banc derrière vous, descendez en fléchissant le genou avant jusqu''à ce que la cuisse soit parallèle au sol, puis remontez en poussant dans le pied avant.', null),
  ('47892ae5-bbcd-4622-90e6-e710dd8e2917', 'Walking Lunge', 'Faites un grand pas en avant et descendez jusqu''à ce que les deux genoux forment un angle droit, puis poussez pour ramener les pieds ensemble à l''avant et enchaînez avec l''autre jambe.', null),
  ('4ec44ea0-4a60-40bc-ad2e-0ca4efa04962', 'Step-Up', 'Face à une marche ou un step, posez tout le pied dessus et poussez pour monter en tendant la jambe, sans vous aider de l''autre jambe, puis redescendez avec contrôle.', null),
  ('8409c244-9437-443d-8fc0-4c31b8384d45', 'Leg Extension', 'Assis, tibias contre les rouleaux de la machine, tendez les jambes jusqu''à l''horizontale, puis redescendez lentement sans relâcher la tension.', null),
  ('bacfd5ad-41a3-4f80-9ded-361c7fbe0956', 'Leg Curl', 'Allongé sur le ventre, chevilles sous les rouleaux de la machine, fléchissez les genoux pour amener les talons vers les fessiers, puis redescendez lentement.', null),
  ('971235e0-020c-44df-8e65-b60ca2588b1b', 'Seated Leg Curl', 'Assis, l''arrière des chevilles contre les rouleaux de la machine, fléchissez les genoux pour amener les chevilles vers l''arrière du siège, puis revenez lentement.', null),
  ('f6bd0bd6-0753-47ea-9fd2-a91774a50f1d', 'Hip Thrust', 'Haut du dos calé contre un banc, genoux fléchis pieds au sol, charge posée sur les hanches, poussez le bassin vers le haut jusqu''à extension complète des hanches, puis redescendez.', null),
  ('e466cece-d226-434c-aa80-978e494c27f3', 'Glute Bridge', 'Allongé sur le dos, genoux fléchis pieds au sol, soulevez le bassin en contractant les fessiers jusqu''à aligner hanches, genoux et épaules, puis redescendez avec contrôle.', null),
  ('2dbb1448-a299-4c8a-9a89-7f39eac27395', 'Good Morning', 'Barre sur le haut du dos, jambes légèrement fléchies, penchez le buste vers l''avant en poussant les hanches vers l''arrière, dos droit, puis redressez-vous en contractant les fessiers.', null),
  ('7c996ef6-623c-452b-9f1a-1b5dc5961ed7', 'Standing Calf Raise', 'Debout, avant-pieds sur une surélévation, montez sur la pointe des pieds le plus haut possible, puis redescendez lentement en laissant les talons descendre sous le niveau des orteils.', null),
  ('116cc641-67d6-4cea-a5a1-be5a4875f751', 'Seated Calf Raise', 'Assis, avant-pieds sur une surélévation, genoux sous les coussinets de charge, montez sur la pointe des pieds, puis redescendez lentement en étirant les mollets.', null),
  ('57c31f27-804a-48c5-9b7f-6ad770cbe3f5', 'Bicep Curl', 'Debout, poids tenu devant les cuisses, fléchissez les coudes pour remonter la charge vers les épaules, coudes fixes le long du corps, puis redescendez lentement.', null),
  ('4a63142c-f67e-4700-ab20-7c9c7fde5ccc', 'Hammer Curl', 'Debout, haltères ou corde tenus en prise neutre (paumes face à face) le long du corps, fléchissez les coudes pour remonter la charge vers les épaules, puis redescendez lentement.', null),
  ('8f768f7c-1c0a-4237-ad6e-b5584aa92236', 'Preacher Curl', 'Bras posés sur le pupitre incliné, fléchissez les coudes pour remonter la charge vers les épaules, puis redescendez lentement sans décoller les bras du support.', null),
  ('691bc92d-ea76-4ae6-aa29-38c441900857', 'Cable Curl', 'Face à la poulie basse, fléchissez les coudes pour remonter la poignée vers les épaules, coudes fixes le long du corps, puis redescendez lentement.', null),
  ('ce1d013d-0ff9-4af9-9b66-3811f6331dd5', 'Reverse Curl', 'Debout, barre tenue devant les cuisses en pronation (paumes vers le bas), fléchissez les coudes pour remonter la barre vers les épaules, coudes fixes, puis redescendez lentement.', null),
  ('ca0dfc6d-8789-4686-b97e-f57744be8735', 'Wrist Curl', 'Avant-bras posé sur une surface, paume vers le haut, laissez le poignet redescendre puis remontez-le en fléchissant le poignet vers le haut, sans bouger l''avant-bras.', null),
  ('149d7c4c-4b8e-4cba-b11d-fa0f1b3d5ac0', 'Tricep Pushdown', 'Face à la poulie haute, coudes fixes le long du corps, tendez les bras vers le bas jusqu''à extension complète, puis remontez lentement.', null),
  ('45589d8a-4b70-47c1-93d2-f2668fbd1539', 'Overhead Tricep Extension', 'Bras tendus au-dessus de la tête, fléchissez les coudes pour descendre la charge derrière la tête, puis retendez les bras jusqu''à extension complète.', null),
  ('959cb0db-dab9-473b-b9df-c5283f693dd2', 'Skull Crusher', 'Allongé sur un banc, bras tendus au-dessus de la poitrine, fléchissez les coudes pour descendre la charge vers le front, puis retendez les bras.', null),
  ('8c3cdab8-6519-4bc4-990c-0162ec0d8756', 'Close-Grip Bench Press', 'Allongé sur le dos, mains rapprochées sur la barre, descendez la barre vers le bas de la poitrine coudes proches du corps, puis repoussez jusqu''à extension des bras.', null),
  ('61e7a153-c430-4c5c-aec5-29901437845a', 'Dip', 'En appui sur des barres parallèles, corps vertical, descendez en fléchissant les coudes, puis repoussez jusqu''à extension des bras.', null),
  ('aaebf507-95ef-4ced-9c2a-2a80b64adc9b', 'Assisted Dip', 'En appui sur des barres parallèles, corps vertical, descendez en fléchissant les coudes, puis repoussez jusqu''à extension des bras.', null),
  ('a2e1d1a3-b4ee-48d3-98b9-bfb9534f5345', 'Plank', 'En appui sur les avant-bras et les pointes de pieds, corps aligné en ligne droite des chevilles à la tête, maintenez la position sans laisser le bassin s''affaisser ou monter.', null),
  ('ebe83c21-b997-4bc5-95a0-bd573ddcf064', 'Side Plank', 'En appui sur un avant-bras et le bord du pied, corps aligné en ligne droite des chevilles à la tête, maintenez la position sans laisser le bassin s''affaisser.', null),
  ('9c704854-378b-4807-98b6-459eaac62ec7', 'Hanging Leg Raise', 'Suspendu à une barre, jambes tendues, levez-les jusqu''à l''horizontale ou plus haut en contractant les abdominaux, puis redescendez avec contrôle.', null),
  ('860e72dd-8967-4c36-a45b-e86ed4d20c06', 'Cable Crunch', 'À genoux face à la poulie haute, corde tenue près du visage, enroulez le buste vers le bas en contractant les abdominaux, puis remontez avec contrôle.', null),
  ('2c36d671-b4f0-475c-b169-f308e7207b01', 'Ab Wheel Rollout', 'À genoux, roue tenue à deux mains devant vous, faites-la rouler vers l''avant en gardant le dos droit et les abdominaux gainés, aussi loin que contrôlable, puis ramenez-la en revenant à la position de départ.', null),
  ('6315517e-eb83-450a-a17a-0ec926a33ee8', 'Running', 'Courez à une allure régulière et confortable, foulée souple, en augmentant progressivement la durée ou la distance.', null),
  ('b474f557-b996-4736-aab5-177334b50878', 'Walking', 'Marchez à une allure régulière, dos droit, en augmentant progressivement la durée ou la distance.', null),
  ('15548226-3784-41ea-9b4d-9d95471a331b', 'Cycling', 'Pédalez à une cadence régulière sur vélo stationnaire ou classique, en ajustant la résistance selon la tolérance.', null),
  ('fece5d95-4f4a-4e97-8fc6-2db1e28d2ddb', 'Rowing', 'Sur un rameur, poussez avec les jambes puis tirez la poignée vers l''abdomen en resserrant les omoplates, dans un enchaînement fluide et régulier.', null),
  ('954a60e6-51c9-4232-9f56-cc9e2addb3f9', 'Stair Climber', 'Sur le monte-escalier, montez à un rythme régulier en gardant le dos droit, sans vous appuyer excessivement sur les mains courantes.', null),
  ('17aae3e9-cb8e-4fc7-b0e5-5b4dac5a5f40', 'Dumbbell Fly', 'Bras légèrement fléchis, ramenez les mains ou les poignées l''une vers l''autre devant la poitrine en un large arc de cercle, puis revenez lentement en laissant les bras s''écarter.', null),
  ('ae8190e5-2879-43fd-85cb-06a85330616e', 'Incline Cable Fly', 'Bras légèrement fléchis, ramenez les mains ou les poignées l''une vers l''autre devant la poitrine en un large arc de cercle, puis revenez lentement en laissant les bras s''écarter.', null),
  ('707e2215-43f4-4907-941d-5a5e27dab90c', 'Decline Dumbbell Press', 'Allongé sur un banc en déclive, haltères au niveau de la poitrine, poussez-les vers le haut jusqu''à extension des bras puis redescendez lentement.', null),
  ('5fe234d8-4e54-4489-8cd0-f3f829e9c566', 'Smith Machine Bench Press', 'Allongé sur le dos, barre ou haltères au niveau de la poitrine, poussez la charge vers le haut jusqu''à extension des bras, puis redescendez lentement en contrôlant la charge jusqu''à toucher légèrement le buste.', null),
  ('2cecd76d-a31d-45fa-9371-cb75026f6c9a', 'Landmine Press', 'Debout, une extrémité de la barre calée au sol, tenez l''autre extrémité au niveau de l''épaule et poussez-la vers le haut et l''avant jusqu''à extension du bras, puis revenez lentement.', null),
  ('5e54c0ad-5b47-402e-b4be-aebed3f5042d', 'Chest Dip', 'En appui sur des barres parallèles, buste légèrement penché en avant, descendez en fléchissant les coudes jusqu''à sentir l''étirement de la poitrine, puis repoussez jusqu''à extension des bras.', null),
  ('844e6d99-de6b-492f-80b9-25be2a0367e2', 'Weighted Dip', 'En appui sur des barres parallèles, corps vertical, descendez en fléchissant les coudes, puis repoussez jusqu''à extension des bras.', null),
  ('7950173c-7de2-4f6c-bd57-9e4e8f6d4636', 'Machine Shoulder Press', 'Assis, charge au niveau des épaules, poussez-la vers le haut jusqu''à extension complète des bras au-dessus de la tête, puis redescendez lentement au niveau des épaules.', null),
  ('fd6a54dd-74c2-40f5-b7a2-0e809b7d4af7', 'Standing Dumbbell Press', 'Debout, un haltère dans chaque main au niveau des épaules, poussez-les vers le haut jusqu''à extension complète des bras au-dessus de la tête, puis redescendez lentement.', null),
  ('0bf7b5b4-794b-43cf-bbd3-aa03be6f0a03', 'Push Press', 'Barre au niveau des épaules, fléchissez légèrement les jambes puis extendez-les d''un mouvement explosif pour aider à pousser la barre au-dessus de la tête jusqu''à extension des bras.', null),
  ('32c34058-175b-400a-adb0-2feca669f797', 'Machine Lateral Raise', 'Debout, un poids dans chaque main le long du corps, levez les bras sur les côtés jusqu''à hauteur d''épaule, coudes légèrement fléchis, puis redescendez lentement.', null),
  ('1c5647c3-6893-4563-9041-d2cd4748d1a5', 'Cable Front Raise', 'Debout, poids devant les cuisses, levez un ou deux bras tendus devant vous jusqu''à hauteur d''épaule, puis redescendez lentement.', null),
  ('dadec409-6f17-4438-90e0-92f89c32d71c', 'Plate Front Raise', 'Debout, poids devant les cuisses, levez un ou deux bras tendus devant vous jusqu''à hauteur d''épaule, puis redescendez lentement.', null),
  ('88e2ca24-2612-4108-8d1d-b761aa56ab67', 'Bent-Over Rear Delt Raise', 'Buste penché en avant, un haltère dans chaque main, bras légèrement fléchis, écartez les bras sur les côtés en resserrant les omoplates, puis revenez lentement.', null),
  ('f0c369c6-b700-4017-bea1-3bd6b7b5d56a', 'Cable Rear Delt Fly', 'Buste penché en avant (ou assis face à la machine), bras légèrement fléchis, écartez les bras sur les côtés en resserrant les omoplates, puis revenez lentement.', null),
  ('fac10475-f689-447a-9de0-6ac99b8b4586', 'Pendlay Row', 'Buste penché en avant, dos droit, tirez la barre vers le bas de l''abdomen en resserrant les omoplates, coudes proches du corps, puis redescendez avec contrôle.', null),
  ('8e5942bb-766f-4c46-b8c6-b0653e2f9382', 'Inverted Row', 'Allongé sous une barre fixe, corps droit et gainé, tirez la poitrine vers la barre en resserrant les omoplates, puis redescendez lentement jusqu''à extension des bras.', null),
  ('78de6d1c-03df-4126-8205-f66299732396', 'Meadows Row', 'Une extrémité de barre calée dans un coin, tenez l''autre extrémité d''une main, buste penché en avant, tirez la charge vers la hanche puis redescendez avec contrôle.', null),
  ('67ae735c-15a3-42dc-8087-74e1f6b8d9ab', 'Single-Arm Cable Row', 'Un genou et une main en appui, dos droit, tirez l''haltère ou la poignée vers la hanche en resserrant l''omoplate, puis redescendez avec contrôle.', null),
  ('351bbbe7-2248-466c-8e8e-2b85a01e5f14', 'Wide-Grip Lat Pulldown', 'Assis face à la poulie haute, tirez la barre vers le haut de la poitrine en resserrant les omoplates, puis remontez avec contrôle jusqu''à extension des bras.', null),
  ('5b8036d7-eddf-4673-88f0-ae8e99a0fbd5', 'Neutral-Grip Pull-up', 'Suspendu à une barre fixe, prise en prise neutre tirez le corps vers le haut jusqu''à ce que le menton dépasse la barre, puis redescendez avec contrôle.', null),
  ('bfc1cbaa-7592-4a96-9500-dd76a54b91c5', 'Assisted Chin-up', 'Suspendu à une barre fixe, prise en supination (paumes vers vous), à l''aide d''un élastique ou d''une machine d''assistance, tirez le corps vers le haut jusqu''à ce que le menton dépasse la barre, puis redescendez avec contrôle.', null),
  ('4d26f9c8-2afa-40a2-962c-7815ffc49a1d', 'Weighted Chin-up', 'Suspendu à une barre fixe, prise en supination (paumes vers vous) tirez le corps vers le haut jusqu''à ce que le menton dépasse la barre avec une charge additionnelle, puis redescendez avec contrôle.', null),
  ('bb0f6428-ae65-4371-97d3-300c05cc445e', 'Rack Pull', 'Barre positionnée en hauteur sur des supports, dos droit, tirez la barre en poussant dans le sol jusqu''à extension complète des hanches, puis reposez-la avec contrôle.', null),
  ('b7395424-5abd-49be-a830-feb58e688c70', 'Back Extension', 'Bassin calé sur le banc à hyperextensions, buste penché vers l''avant, redressez le buste jusqu''à l''horizontale en contractant le bas du dos et les fessiers, puis redescendez avec contrôle.', null),
  ('07fd621a-b71d-4b68-ace2-190578bf0e20', 'Dumbbell Shrug', 'Debout, poids dans chaque main le long du corps, remontez les épaules vers les oreilles sans fléchir les coudes, maintenez brièvement, puis redescendez avec contrôle.', null),
  ('f03858a3-6277-4bda-9e0c-d11382b25c1f', 'Goblet Squat', 'Debout, un poids tenu à deux mains contre la poitrine, descendez en fléchissant les hanches et les genoux jusqu''à ce que les cuisses soient parallèles au sol, dos droit, puis remontez.', null),
  ('adf6b0cb-a94b-42ad-9a57-174e781f17e5', 'Smith Machine Squat', 'Barre guidée posée sur le haut du dos, pieds légèrement devant les hanches, descendez en fléchissant les hanches et les genoux jusqu''à ce que les cuisses soient parallèles au sol, puis remontez.', null),
  ('3056f431-5e8b-4f6a-9d2e-9bcf0bcaccc3', 'Belt Squat', 'Charge suspendue à une ceinture au niveau des hanches, descendez en fléchissant les hanches et les genoux jusqu''à ce que les cuisses soient parallèles au sol, dos droit, puis remontez.', null),
  ('59bb3aa6-99fb-44a6-89bc-492c8b30b5c3', 'Sumo Deadlift', 'Pieds très écartés, pointes tournées vers l''extérieur, barre au sol, saisissez-la à l''intérieur des jambes puis redressez-vous en poussant dans le sol jusqu''à extension complète des hanches, dos droit.', null),
  ('bf52032a-e810-4f82-87c9-39d0f981650f', 'Trap Bar Deadlift', 'Debout à l''intérieur d''une barre hexagonale, saisissez les poignées, dos droit, redressez-vous en poussant dans le sol jusqu''à extension complète des hanches et des genoux.', null),
  ('b04e7c4d-456c-4115-a948-19df317c6059', 'Lying Leg Curl', 'Allongé sur le ventre, chevilles sous les rouleaux de la machine, fléchissez les genoux pour amener les talons vers les fessiers, puis redescendez lentement.', null),
  ('69f80c66-988c-40de-9128-6833e9a18970', 'Nordic Hamstring Curl', 'À genoux, chevilles maintenues fixes, laissez le buste basculer lentement vers l''avant en résistant avec l''arrière des cuisses, le plus longtemps possible, puis rattrapez-vous avec les mains.', null),
  ('70bbd8fc-49fd-4c8e-bba2-baa07b4d9921', 'Single-Leg Romanian Deadlift', 'En appui sur une jambe, dos droit, penchez le buste vers l''avant en tendant l''autre jambe vers l''arrière jusqu''à sentir l''étirement à l''arrière de la cuisse d''appui, puis remontez avec contrôle.', null),
  ('f348703e-b281-4186-9825-9243370810f0', 'Reverse Lunge', 'Faites un grand pas en arrière et descendez jusqu''à ce que les deux genoux forment un angle droit, puis repoussez pour revenir à la position de départ.', null),
  ('e659b74e-f1fa-4722-a7c3-e9aa617ac3a6', 'Split Squat', 'En fente avant, arrière ou latérale selon la variante, descendez jusqu''à ce que les genoux forment un angle droit, dos droit, puis remontez en poussant dans le pied avant.', null),
  ('8de3d81b-7037-4461-a6f3-ac8fe6786fff', 'Cable Kickback', 'Face à la poulie basse, manchette fixée à la cheville, tendez la jambe vers l''arrière en contractant le fessier, puis revenez lentement.', null),
  ('bd97ded0-c1a6-490f-9969-065ecbd16007', 'Hip Abduction Machine', 'En position assise (machine) ou debout à la poulie, écartez la jambe sur le côté contre la résistance, puis revenez lentement.', null),
  ('db6003ea-82cd-4738-b61c-4d14a17b6618', 'Single-Leg Glute Bridge', 'Allongé sur le dos, un genou fléchi pied au sol, l''autre jambe tendue, soulevez le bassin en poussant dans le pied au sol jusqu''à aligner hanches et épaules, puis redescendez.', null),
  ('f1ee442f-fecb-4937-943a-c12208fe2dfd', 'Barbell Glute Bridge', 'Allongé sur le dos, genoux fléchis pieds au sol, soulevez le bassin en contractant les fessiers jusqu''à aligner hanches, genoux et épaules, puis redescendez avec contrôle.', null),
  ('2b64c074-98db-4f76-8626-966f7bb1079d', 'Dumbbell Glute Bridge', 'Allongé sur le dos, genoux fléchis pieds au sol, soulevez le bassin en contractant les fessiers jusqu''à aligner hanches, genoux et épaules, puis redescendez avec contrôle.', null),
  ('e4b94b46-e82a-4db0-a044-3b2ed3be899e', 'Dumbbell Hip Thrust', 'Haut du dos calé contre un banc, genoux fléchis pieds au sol, charge posée sur les hanches, poussez le bassin vers le haut jusqu''à extension complète des hanches, puis redescendez.', null),
  ('773b86c8-bc12-444c-9c8a-c08576c042c7', 'Smith Machine Hip Thrust', 'Haut du dos calé contre un banc, genoux fléchis pieds au sol, charge posée sur les hanches, poussez le bassin vers le haut jusqu''à extension complète des hanches, puis redescendez.', null),
  ('9132697a-36c8-4ad7-8378-20aaf7fa2f26', 'Smith Machine Romanian Deadlift', 'Debout, charge dans les mains, jambes presque tendues, penchez le buste vers l''avant en poussant les hanches vers l''arrière, dos droit, jusqu''à sentir l''étirement à l''arrière des cuisses, puis remontez.', null),
  ('7cca1684-a86e-4892-ac49-576734d1842f', 'Dumbbell Romanian Deadlift', 'Debout, charge dans les mains, jambes presque tendues, penchez le buste vers l''avant en poussant les hanches vers l''arrière, dos droit, jusqu''à sentir l''étirement à l''arrière des cuisses, puis remontez.', null),
  ('cf81709c-c2e1-4d90-847a-34823a7ea16a', 'Kettlebell Romanian Deadlift', 'Debout, charge dans les mains, jambes presque tendues, penchez le buste vers l''avant en poussant les hanches vers l''arrière, dos droit, jusqu''à sentir l''étirement à l''arrière des cuisses, puis remontez.', null),
  ('7ab85058-2e1e-4b77-b0f1-80d982dd47e4', 'Cable Pull-Through', 'Dos à la poulie basse, corde entre les jambes, penchez le buste vers l''avant en poussant les hanches vers l''arrière, puis redressez-vous en contractant les fessiers jusqu''à extension complète des hanches.', null),
  ('694b902b-e23c-461c-a415-a04ab67522f8', 'Machine Glute Kickback', 'En appui sur la machine, pied contre la plateforme, poussez la jambe vers l''arrière en contractant le fessier, puis revenez lentement.', null),
  ('9384a17f-88fa-48f6-b13f-87fc118347f2', 'Cable Standing Hip Abduction', 'En position assise (machine) ou debout à la poulie, écartez la jambe sur le côté contre la résistance, puis revenez lentement.', null),
  ('a1fbeee1-7b79-4a3c-887e-f092e26f97b4', 'Cable Standing Hip Adduction', 'En position assise (machine) ou debout à la poulie, ramenez la jambe vers l''intérieur du corps contre la résistance, puis revenez lentement.', null),
  ('2142cebf-94c1-4e70-8db5-87fd36353789', 'Hip Adduction Machine', 'En position assise (machine) ou debout à la poulie, ramenez la jambe vers l''intérieur du corps contre la résistance, puis revenez lentement.', null),
  ('fe6b5df2-2466-4df7-8e82-acdda60d9e3a', 'Smith Machine Bulgarian Split Squat', 'Pied arrière posé sur un banc derrière vous, descendez en fléchissant le genou avant jusqu''à ce que la cuisse soit parallèle au sol, puis remontez en poussant dans le pied avant.', null),
  ('b067b395-a02e-4a3f-9e4a-3f265e6b1720', 'Smith Machine Reverse Lunge', 'Faites un grand pas en arrière et descendez jusqu''à ce que les deux genoux forment un angle droit, puis repoussez pour revenir à la position de départ.', null),
  ('8aae7f12-4538-41cf-a9fd-aa2a5cf85541', 'Smith Machine Split Squat', 'Barre guidée sur le haut du dos, en fente avant ou arrière selon la variante, descendez jusqu''à ce que les deux genoux forment un angle droit, puis remontez.', null),
  ('5a7203b2-1bd2-4cf2-a485-88867c64f964', 'Heel-Elevated Goblet Squat', 'Debout, un poids tenu à deux mains contre la poitrine, descendez en fléchissant les hanches et les genoux jusqu''à ce que les cuisses soient parallèles au sol, dos droit, puis remontez.', null),
  ('9ed7fd4f-e4e2-4dfd-8db7-79547dce23f4', 'Dumbbell Sumo Squat', 'Pieds très écartés, pointes tournées vers l''extérieur, un haltère tenu à deux mains entre les jambes, descendez en fléchissant les hanches et les genoux, dos droit, puis remontez.', null),
  ('78e4664c-aefc-4e51-a1e9-6b1e644dee6b', 'Dumbbell Sumo Deadlift', 'Pieds très écartés, pointes tournées vers l''extérieur, barre au sol, saisissez-la à l''intérieur des jambes puis redressez-vous en poussant dans le sol jusqu''à extension complète des hanches, dos droit.', null),
  ('08a93e20-e340-4205-9815-91c0a53c2d2b', 'Front-Foot Elevated Split Squat', 'Pied avant posé sur une petite surélévation, descendez en fléchissant le genou avant jusqu''à ce que la cuisse soit parallèle au sol, puis remontez en poussant dans le pied avant.', null),
  ('8ed8649d-75dc-44b8-8fbb-65af7822250b', 'Deficit Reverse Lunge', 'Faites un grand pas en arrière et descendez jusqu''à ce que les deux genoux forment un angle droit, puis repoussez pour revenir à la position de départ.', null),
  ('ef026e3f-881a-4e99-905e-0419daf5ed78', 'Dumbbell Lateral Lunge', 'Faites un grand pas sur le côté et fléchissez ce genou en gardant l''autre jambe tendue, hanches basses, puis repoussez pour revenir au centre.', null),
  ('a47b909e-4588-4d3a-9e3a-1130aac85dd2', 'Dumbbell Curtsy Lunge', 'Faites un pas en arrière et sur le côté en croisant la jambe derrière l''autre, descendez jusqu''à ce que le genou arrière frôle le sol, puis repoussez pour revenir à la position de départ.', null),
  ('f85c9ed5-ad46-4a96-87ff-66267620e32c', 'Landmine Squat', 'Extrémité libre d''une barre calée au sol tenue à deux mains contre la poitrine, descendez en fléchissant les hanches et les genoux jusqu''à ce que les cuisses soient parallèles au sol, puis remontez.', null),
  ('4da488ae-635b-49aa-82c4-6355c160c179', 'Landmine Romanian Deadlift', 'Debout, charge dans les mains, jambes presque tendues, penchez le buste vers l''avant en poussant les hanches vers l''arrière, dos droit, jusqu''à sentir l''étirement à l''arrière des cuisses, puis remontez.', null),
  ('911bc982-4237-4a23-a4ae-b2764d18af0a', 'Kettlebell Swing', 'Pieds écartés largeur de hanches, kettlebell tenue à deux mains, faites-la passer entre les jambes en fléchissant les hanches puis propulsez-la jusqu''à hauteur de poitrine par une extension explosive des hanches.', null),
  ('b81ef2a6-354a-4161-8228-7ddb6dcd86e0', 'Glute-Focused Back Extension', 'Bassin calé sur le banc à hyperextensions, buste penché vers l''avant, redressez le buste jusqu''à l''horizontale en contractant le bas du dos et les fessiers, puis redescendez avec contrôle.', null),
  ('4789b9e0-ac80-47b4-80a5-7a36288794fa', 'Reverse Hyperextension', 'Buste calé sur un banc, jambes tendues dans le vide, levez les jambes vers l''arrière et le haut en contractant les fessiers et le bas du dos, puis redescendez avec contrôle.', null),
  ('a6817000-9289-4eb9-b56f-2c1da6a7d05b', 'Donkey Calf Raise', 'Buste penché en avant en appui sur un support, avant-pieds sur une surélévation, montez sur la pointe des pieds le plus haut possible, puis redescendez lentement en étirant les mollets.', null),
  ('de8f2feb-f64e-4a94-9d89-e642834d2e3c', 'Leg Press Calf Raise', 'Assis à la presse à cuisses, avant-pieds sur le bas de la plateforme, poussez en pointant les pieds pour monter la charge, puis redescendez lentement en étirant les mollets.', null),
  ('6786ac6a-e359-4b15-bfce-b3cc61998636', 'Wall Sit', 'Dos appuyé contre un mur, descendez jusqu''à ce que les cuisses soient parallèles au sol, genoux à angle droit, et maintenez la position.', null),
  ('92e2af84-5bea-4b7d-854d-11a701eda009', 'Jump Squat', 'Pieds largeur d''épaules, descendez en position de squat puis propulsez-vous vers le haut en un saut, en amortissant la réception en refléchissant immédiatement les genoux.', null),
  ('8427308c-de05-4fc1-ac9f-74fd72f45799', 'Incline Dumbbell Curl', 'Allongé sur un banc incliné, bras pendant le long du corps, fléchissez les coudes pour remonter les haltères vers les épaules, puis redescendez lentement.', null),
  ('d1608793-5e5f-4cce-8041-852843872f38', 'Concentration Curl', 'Assis, coude calé contre l''intérieur de la cuisse, fléchissez le coude pour remonter l''haltère vers l''épaule, puis redescendez lentement.', null),
  ('c92ebe77-894d-4fa0-8815-82b3b4bf92ee', 'EZ-Bar Curl', 'Debout, barre EZ tenue devant les cuisses, fléchissez les coudes pour remonter la barre vers les épaules, coudes fixes le long du corps, puis redescendez lentement.', null),
  ('0ead8035-20e7-49fe-bddd-b707cff96a4b', 'Spider Curl', 'Poitrine appuyée contre un banc incliné, bras pendant vers le sol, fléchissez les coudes pour remonter la charge vers les épaules, puis redescendez lentement.', null),
  ('0d8518e8-4417-44bc-8fb5-cbbe47f267fb', 'Rope Hammer Curl', 'Debout, haltères ou corde tenus en prise neutre (paumes face à face) le long du corps, fléchissez les coudes pour remonter la charge vers les épaules, puis redescendez lentement.', null),
  ('9896cae1-c40f-44f2-8519-9ad2f72687f8', 'Drag Curl', 'Debout, barre tenue devant les cuisses, fléchissez les coudes en faisant glisser la barre le long du corps vers le haut, coudes reculant vers l''arrière, puis redescendez lentement.', null),
  ('2e2136e8-615e-4d5f-86d5-b76b0a61df72', 'Rope Tricep Pushdown', 'Face à la poulie haute, coudes fixes le long du corps, tendez les bras vers le bas jusqu''à extension complète, puis remontez lentement.', null),
  ('46aaa2cc-99a0-4fb0-bb96-9c55a4b7422c', 'Two Dumbbell Skullcrusher', 'Allongé sur un banc, bras tendus au-dessus de la poitrine, fléchissez les coudes pour descendre la charge vers le front, puis retendez les bras.', null),
  ('118a62fc-ea8c-4627-9d0b-d6aea60a5294', 'Single Dumbbell Skullcrusher', 'Allongé sur un banc, bras tendus au-dessus de la poitrine, fléchissez les coudes pour descendre la charge vers le front, puis retendez les bras.', null),
  ('19280a6c-0c93-4e4c-8351-4a01603b2a45', 'Dumbbell Overhead Tricep Extension', 'Bras tendus au-dessus de la tête, fléchissez les coudes pour descendre la charge derrière la tête, puis retendez les bras jusqu''à extension complète.', null),
  ('56f8a54b-3592-433a-8e4c-68a5ffd45730', 'Single Arm Dumbbell Tricep Extension', 'Coudes fixes, tendez les bras contre la résistance jusqu''à extension complète, puis revenez lentement en contrôlant la charge.', null),
  ('aee0379e-7b9f-4626-86a3-f31c886f6a92', 'Bench Dip', 'Mains posées sur le bord d''un banc derrière vous, jambes tendues devant, fléchissez les coudes pour descendre le bassin vers le sol, puis repoussez jusqu''à extension des bras.', null),
  ('8777781e-2bcb-4f8f-8f94-f5e8ae8bbb79', 'Tricep Kickback', 'Buste penché en avant, bras à l''horizontale coude fléchi, tendez l''avant-bras vers l''arrière jusqu''à extension complète, puis revenez lentement.', null),
  ('5cf7c9f7-aaf2-4a4e-a98f-5dbb54c45227', 'Wrist Extension', 'Avant-bras posé sur une surface, paume vers le bas, laissez le poignet redescendre puis remontez-le en tendant le poignet vers le haut, sans bouger l''avant-bras.', null),
  ('18b101b0-de7a-4a34-b807-75380f4f8d65', 'Farmer Carry', 'Debout, une charge lourde dans chaque main, épaules basses et gainage engagé, marchez en petits pas réguliers sur la distance ou le temps prévu.', null),
  ('196c3cde-1afb-4c9f-b092-eced815babc0', 'Crunch', 'Allongé sur le dos, genoux fléchis, mains derrière la tête ou croisées sur la poitrine, décollez les épaules du sol en contractant les abdominaux, puis redescendez avec contrôle.', null),
  ('425780b9-8431-4c96-9367-86f772aac6ba', 'Reverse Crunch', 'Allongé sur le dos, genoux fléchis vers la poitrine, décollez le bassin du sol en enroulant le bas du dos, puis redescendez avec contrôle.', null),
  ('44889ddd-5c35-4288-8481-8b90b8ddd002', 'Russian Twist', 'Assis, buste légèrement penché en arrière, pieds décollés ou posés au sol, faites pivoter le buste d''un côté à l''autre en amenant les mains près du sol de chaque côté.', null),
  ('186c714a-5520-417e-91b3-c947839ee352', 'Bicycle Crunch', 'Allongé sur le dos, mains derrière la tête, amenez alternativement un coude vers le genou opposé en pédalant avec les jambes, sans tirer sur la nuque.', null),
  ('61524ab2-0477-46b7-9ddd-a32d9264750a', 'Mountain Climber', 'En position de planche haute, mains sous les épaules, ramenez rapidement un genou puis l''autre vers la poitrine en alternance, bassin stable, à un rythme soutenu.', null),
  ('712f3d25-a6f2-4797-8c97-3f4ce9724cd4', 'Dead Bug', 'Allongé sur le dos, bras tendus vers le plafond, genoux fléchis à la verticale, descendez lentement un bras et la jambe opposée vers le sol sans décoller le bas du dos, puis revenez et alternez.', null),
  ('0ab86962-cd40-43f1-8ff2-5a95814bf394', 'Bird Dog', 'À quatre pattes, dos plat, tendez simultanément un bras devant vous et la jambe opposée derrière vous, sans faire pivoter le bassin, puis revenez et alternez.', null),
  ('a85d55e7-83bc-452a-adb2-277ab5701d46', 'Pallof Press', 'Debout de côté par rapport à la poulie ou l''élastique, poignée tenue devant la poitrine, tendez les bras devant vous en résistant à la rotation du buste, puis ramenez les mains à la poitrine.', null),
  ('09feaf41-3fcb-4ce9-94bb-835ae8b75641', 'Cable Woodchop', 'Debout de côté par rapport à la poulie ou l''élastique fixé en hauteur, tirez la poignée en diagonale vers la hanche opposée en faisant pivoter le buste, puis revenez avec contrôle.', null),
  ('d86b2bcd-3387-4f56-aaa9-cfa1b561b46f', 'Half-Kneeling Pallof Press', 'En fente basse, un genou au sol, poignée de la poulie tenue devant la poitrine, tendez les bras devant vous en résistant à la rotation du buste, puis ramenez les mains à la poitrine.', null),
  ('99c8e406-95ef-41d5-b8a4-9315c113ddba', 'Cable Pallof Hold', 'Debout de côté par rapport à la poulie, bras tendus devant la poitrine, maintenez la position sans laisser le buste pivoter vers la résistance.', null),
  ('9f37cdd6-ec63-4fb8-ba66-40bbf1851faa', 'Hanging Knee Raise', 'Suspendu à une barre ou en appui sur les avant-bras, genoux fléchis, levez les genoux vers la poitrine en contractant les abdominaux, puis redescendez avec contrôle.', null),
  ('9cb20741-6d63-470f-ae91-d8d311c1185b', 'Captain''s Chair Knee Raise', 'Suspendu à une barre ou en appui sur les avant-bras, genoux fléchis, levez les genoux vers la poitrine en contractant les abdominaux, puis redescendez avec contrôle.', null),
  ('1a4ef6ae-71a1-4af0-817e-d934975c25a3', 'Decline Sit-Up', 'Allongé sur un banc en déclive, pieds calés, redressez le buste jusqu''à la verticale en contractant les abdominaux, puis redescendez avec contrôle.', null),
  ('6eb686d5-d788-4d55-a309-90f3cf9b3b37', 'Weighted Crunch', 'Allongé sur le dos, genoux fléchis, mains derrière la tête ou croisées sur la poitrine, décollez les épaules du sol en contractant les abdominaux, puis redescendez avec contrôle.', null),
  ('80055c3b-0095-4a3d-8beb-0aac1ec84110', 'Weighted Russian Twist', 'Assis, buste légèrement penché en arrière, pieds décollés ou posés au sol, faites pivoter le buste d''un côté à l''autre en amenant les mains près du sol de chaque côté.', null),
  ('965f966e-c38d-4b03-86f7-0aca46d0797f', 'Dumbbell Side Bend', 'Debout, un haltère dans une main le long du corps, penchez le buste latéralement en laissant descendre l''haltère le long de la jambe, puis remontez en contractant l''oblique.', null),
  ('b9b6244d-1684-4234-86dd-5089429dfde4', 'Elliptical', 'Sur un vélo elliptique, maintenez un mouvement fluide et régulier des jambes et des bras, en ajustant la résistance selon la tolérance.', null),
  ('c48231a0-e39c-492a-824a-83d5e322425a', 'Swimming', 'Nagez à un rythme régulier et confortable, en adaptant la nage et l''intensité à vos capacités.', null),
  ('4b5d8a3d-6240-4cab-be9a-223d7e9c8505', 'Jump Rope', 'Sautez à la corde à un rythme régulier, petits sauts sur l''avant des pieds, coudes proches du corps.', null),
  ('9c47bd18-f0f4-49e7-9d91-2461004c4081', 'Assault Bike', 'Sur le vélo à bras, pédalez en poussant et tirant simultanément les bras, à une cadence régulière.', null),
  ('c875ecb9-8b66-41e1-bdd8-021add177b67', 'SkiErg', 'Sur le SkiErg, tirez les poignées vers le bas en fléchissant les hanches, dans un mouvement fluide imitant le ski de fond.', null),
  ('fb9642ed-9444-4e1e-95c8-a01506517742', 'Hiking', 'Marchez sur terrain varié à une allure confortable, en adaptant le rythme aux dénivelés.', null),
  ('87d5dbf1-a2cc-4867-8a5b-e04d53da19a3', 'Treadmill Incline Walk', 'Marchez sur tapis roulant incliné à une allure régulière, dos droit, en ajustant la pente selon la tolérance.', null),
  ('1b50d300-e521-45d6-99fa-6e7aa24812a3', 'Battle Ropes', 'Debout, une extrémité de corde dans chaque main, faites onduler les cordes en alternance ou simultanément à un rythme soutenu.', null),
  ('066ba8c4-1955-468f-b1f2-32ec05dec7ea', 'Incline Push-up', 'Mains posées sur un support surélevé (banc, marche), corps gainé et droit, fléchissez les coudes pour descendre la poitrine vers l''appui puis repoussez jusqu''à extension des bras.', null),
  ('a730c2bc-9320-4f06-b7f6-b03d8146a2c8', 'Knee Push-up', 'Genoux au sol, mains légèrement plus larges que les épaules, fléchissez les coudes pour descendre la poitrine vers le sol puis repoussez jusqu''à extension des bras.', null),
  ('5cbb9b87-ae7b-4e6e-84da-f9d073d92928', 'Wide Push-up', 'Mains posées nettement plus larges que les épaules, fléchissez les coudes pour descendre la poitrine vers le sol puis repoussez jusqu''à extension des bras.', null),
  ('bf5c697d-c10b-4435-bb4c-72ae3f0e9afa', 'Diamond Push-up', 'Mains rapprochées sous la poitrine, pouces et index formant un losange, fléchissez les coudes en les gardant proches du corps pour descendre puis repoussez jusqu''à extension des bras.', null),
  ('4d53d3b7-9f0e-411b-8fce-a28c0aa567bd', 'Decline Push-up', 'Pieds posés sur un support surélevé, mains au sol sous les épaules, fléchissez les coudes pour descendre la poitrine vers le sol puis repoussez jusqu''à extension des bras.', null),
  ('94fda88a-d59f-4c2c-add2-0fef469d5ab3', 'Pike Push-up', 'Fesses hautes, corps en V inversé (pieds surélevés pour la variante avancée), fléchissez les coudes pour amener le sommet du crâne vers le sol puis repoussez jusqu''à extension des bras.', null),
  ('8493a9d5-a5ab-400f-b537-f061e368cedf', 'Feet-Elevated Pike Push-up', 'Fesses hautes, corps en V inversé (pieds surélevés pour la variante avancée), fléchissez les coudes pour amener le sommet du crâne vers le sol puis repoussez jusqu''à extension des bras.', null),
  ('5c026d9f-2341-49e3-a00b-516d5df7269d', 'Archer Push-up', 'Mains très écartées, descendez en pliant un bras tout en gardant l''autre tendu sur le côté, puis repoussez et alternez de côté.', null),
  ('4523f87d-8721-4e9a-bd80-fdae92f29349', 'Typewriter Push-up', 'En position basse de pompe, mains très écartées, déplacez le poids d''un côté à l''autre en gardant la poitrine proche du sol, comme un chariot de machine à écrire.', null),
  ('d381889e-d2ce-4cd3-89b4-758865cc5c07', 'Explosive Push-up', 'En position de pompe, descendez normalement puis repoussez avec assez de puissance pour décoller brièvement les mains du sol, en amortissant la réception.', null),
  ('48f02a05-7ae0-4ee1-a11b-d2a3e17aab09', 'Hindu Push-up', 'Départ fesses hautes, plongez le buste vers le sol en un mouvement fluide vers l''avant jusqu''à redresser le torse, bras tendus, bassin proche du sol, puis repartez en sens inverse.', null),
  ('eb357637-3f2f-4563-a0c5-5754f69d9360', 'Scapular Push-up', 'En position de planche haute, bras tendus, laissez les omoplates se rapprocher en abaissant légèrement le buste entre les bras, puis repoussez le sol en écartant les omoplates, coudes toujours tendus.', null),
  ('ad29e0cd-e0a0-44e4-bad5-fa69ef1c3d18', 'Push-up Shoulder Tap', 'En position de planche haute, mains sous les épaules, touchez alternativement l''épaule opposée avec chaque main en gardant le bassin stable, sans balancer.', null),
  ('75037aed-7569-4b67-98b6-bb6bec9c51f4', 'Wall Push-up', 'Debout face à un mur, mains posées à plat à hauteur d''épaules, fléchissez les coudes pour rapprocher la poitrine du mur puis repoussez jusqu''à extension des bras.', null),
  ('9e39df37-d092-4e66-a8f6-b5767e2898ec', 'Wall Walk', 'En position de planche, pieds contre un mur, marchez avec les pieds le long du mur en vous rapprochant en même temps avec les mains, jusqu''à une position quasi verticale, puis redescendez.', null),
  ('70a9edc1-f621-41d0-955f-8838d16f9fe6', 'Wall Handstand Push-up', 'En appui renversé contre un mur, mains au sol sous les épaules, fléchissez les coudes pour descendre la tête vers le sol puis repoussez jusqu''à extension complète des bras.', null),
  ('132973a1-50e5-4cf3-9c26-e29d4fbdd89b', 'Handstand Push-up', 'En appui renversé contre un mur, mains au sol sous les épaules, fléchissez les coudes pour descendre la tête vers le sol puis repoussez jusqu''à extension complète des bras.', null),
  ('19637837-023e-4fa0-bba3-7de1efd2e280', 'Chair Dip', 'Mains posées sur le bord d''une chaise derrière vous, fléchissez les coudes pour descendre le bassin, puis repoussez jusqu''à extension des bras.', null),
  ('b3083a7f-3f6c-400b-aee0-d7cda78da649', 'Doorway Row', 'Debout, mains agrippées au cadre d''une porte, penchez le buste en arrière bras tendus puis tirez la poitrine vers les mains en resserrant les omoplates, avant de revenir lentement.', null),
  ('6696a80f-d6bf-4ac6-91d7-2c8461409c9d', 'Towel Row', 'Serviette enroulée autour d''un point d''ancrage stable, tenez chaque extrémité, penchez le buste en arrière puis tirez la poitrine vers les mains en resserrant les omoplates.', null),
  ('a2092948-7fc6-4d01-aef2-5034d015d649', 'Prone Y Raise', 'Allongé sur le ventre sur un banc incliné, bras tendus formant un Y, levez légèrement les bras vers le plafond en resserrant les omoplates, puis redescendez avec contrôle.', null),
  ('f8473939-3161-44fc-8326-cf65363b2b85', 'Prone T Raise', 'Allongé sur le ventre sur un banc incliné, bras tendus formant un T, levez légèrement les bras vers le plafond en resserrant les omoplates, puis redescendez avec contrôle.', null),
  ('3c7a9006-1232-4766-a158-56d1d7b13295', 'Superman', 'Allongé sur le ventre, bras tendus devant vous, soulevez simultanément bras, poitrine et jambes du sol puis redescendez avec contrôle.', null),
  ('65b1f5d4-5b2b-4db4-88aa-1582b6dec5be', 'Superman Hold', 'Allongé sur le ventre, bras tendus devant vous, soulevez simultanément bras, poitrine et jambes du sol et maintenez la position quelques secondes.', null),
  ('19210566-c713-4cfd-8e49-a41bf3f455f0', 'Reverse Snow Angel', 'Allongé sur le ventre, bras le long du corps, levez légèrement le buste et faites glisser les bras vers l''avant en arc de cercle comme pour dessiner un ange, puis revenez.', null),
  ('16ea3c4a-74b1-43a0-a782-51a59a7be6c1', 'Dead Hang', 'Suspendu à une barre fixe, bras tendus, relâchez les épaules (dead hang) ou gardez-les légèrement engagées (active hang), et maintenez la position.', null),
  ('c87216c0-8313-4890-9ed5-3f36cc463005', 'Active Hang', 'Suspendu à une barre fixe, bras tendus, relâchez les épaules (dead hang) ou gardez-les légèrement engagées (active hang), et maintenez la position.', null),
  ('0c94663e-9de5-4618-b484-693a68b7fe20', 'Scapular Pull-up', 'Suspendu à une barre fixe, bras tendus, sans fléchir les coudes, abaissez puis remontez les épaules en initiant le mouvement par les omoplates.', null),
  ('762db505-2eae-4384-9958-519f66a68e3f', 'Negative Pull-up', 'Menton au-dessus de la barre (aidez-vous d''un support pour monter), descendez le plus lentement possible jusqu''à extension complète des bras.', null),
  ('dec5b911-b66a-4623-be6b-ab4bb6cdcaa8', 'Commando Pull-up', 'Suspendu à une barre, mains l''une devant l''autre, tirez le corps vers le haut en alternant la tête de chaque côté de la barre, puis redescendez avec contrôle.', null),
  ('4f45a15f-32b4-4f11-a689-a7d34f731387', 'L-Sit Pull-up', 'Suspendu à une barre, jambes tendues à l''horizontale devant vous, tirez le corps vers le haut jusqu''à ce que le menton dépasse la barre, puis redescendez avec contrôle.', null),
  ('1a1ad00d-8c44-48d5-b762-694b12f506b3', 'Towel Pull-up', 'Suspendu à deux serviettes passées sur une barre, tirez le corps vers le haut jusqu''à ce que le menton dépasse la barre, puis redescendez avec contrôle.', null),
  ('4258d669-83b8-4f94-8db6-7fe8f5c219b4', 'Bodyweight Squat', 'Pieds largeur d''épaules, descendez en fléchissant les hanches et les genoux comme pour vous asseoir, dos droit, jusqu''à ce que les cuisses soient parallèles au sol, puis remontez.', null),
  ('eb50ea89-0e4d-418a-adde-d9295f2f51e2', 'Pistol Squat', 'En équilibre sur une jambe, l''autre tendue devant vous, descendez en fléchissant le genou d''appui jusqu''à ce que la hanche passe sous le genou, puis remontez.', null),
  ('b3d07ba9-af66-4773-8008-f5661a9b5aa9', 'Assisted Pistol Squat', 'En vous tenant à un support, En équilibre sur une jambe, l''autre tendue devant vous, descendez en fléchissant le genou d''appui jusqu''à ce que la hanche passe sous le genou, puis remontez.', null),
  ('cab38a37-485b-4fed-92ed-147915f66b71', 'Shrimp Squat', 'En équilibre sur une jambe, tenez l''autre pied derrière vous avec la main, descendez en fléchissant le genou d''appui jusqu''à ce que le genou arrière touche presque le sol, puis remontez.', null),
  ('56c3f8fb-9750-4fa4-b90c-3eb2e2df1379', 'Cossack Squat', 'Pieds très écartés, transférez le poids d''un côté en fléchissant ce genou et en descendant les hanches vers le talon, l''autre jambe restant tendue, puis revenez au centre et alternez.', null),
  ('30b8c6f8-10fc-455f-a7a7-01efec364834', 'Sissy Squat', 'Debout, talons légèrement décollés, penchez le buste et les genoux vers l''avant en gardant le corps droit des genoux à la tête, jusqu''à sentir l''étirement à l''avant des cuisses, puis remontez.', null),
  ('f8c614c4-5945-4947-becd-eb2e3f24a2cc', 'Forward Lunge', 'Faites un grand pas en avant et descendez jusqu''à ce que les deux genoux forment un angle droit, puis repoussez pour revenir à la position de départ.', null),
  ('ae0984c9-2fdb-4450-9c7d-56597deb444d', 'Lateral Lunge', 'Faites un grand pas sur le côté et fléchissez ce genou en gardant l''autre jambe tendue, hanches basses, puis repoussez pour revenir au centre.', null),
  ('41a9e5d6-6712-4cab-8237-8b19247e0e7e', 'Curtsy Lunge', 'Faites un pas en arrière et sur le côté en croisant la jambe derrière l''autre, descendez jusqu''à ce que le genou arrière frôle le sol, puis repoussez pour revenir à la position de départ.', null),
  ('1ec486b1-5617-4127-90db-e9e3666e56fe', 'Skater Squat', 'En équilibre sur une jambe, l''autre jambe fléchie en arrière sans toucher le sol, descendez en fléchissant le genou d''appui jusqu''à effleurer le genou arrière au sol, puis remontez.', null),
  ('60ffaea8-e747-48d0-8d69-aa88d102756d', 'Single-Leg Box Squat', 'En équilibre sur une jambe devant une chaise ou un banc bas, descendez en fléchissant le genou d''appui jusqu''à toucher légèrement l''assise, puis remontez.', null),
  ('52207c5a-5057-4a19-ba0a-29a45de976d0', 'Step-Down', 'Debout sur une marche ou un step, descendez lentement une jambe vers le sol en contrôlant la flexion du genou d''appui, sans poser complètement le pied, puis remontez.', null),
  ('31fb5334-6049-453d-888f-a1009c47407c', 'Calf Raise', 'Debout, avant-pieds sur une surélévation, montez sur la pointe des pieds le plus haut possible, puis redescendez lentement en laissant les talons descendre sous le niveau des orteils.', null),
  ('f0d912cf-2189-409c-94f1-49b0387f30b2', 'Single-Leg Calf Raise', 'En équilibre sur une jambe, avant-pied sur une surélévation, montez sur la pointe du pied le plus haut possible, puis redescendez lentement en étirant le mollet.', null),
  ('14270b5a-d243-42ce-bed4-69574ec5f8a3', 'Glute Bridge March', 'Allongé sur le dos, genoux fléchis, bassin soulevé en pont, levez un genou vers la poitrine sans laisser le bassin redescendre, reposez le pied puis alternez.', null),
  ('21d41551-2dc4-476e-a9b0-a60414a76405', 'Frog Pump', 'Allongé sur le dos, plantes de pieds jointes, genoux ouverts vers l''extérieur, soulevez le bassin en contractant les fessiers, puis redescendez avec contrôle.', null),
  ('e479b2f5-a0dd-4c6a-ab3a-3b2c86813b37', 'Donkey Kick', 'À quatre pattes, genou fléchi à angle droit, poussez le talon vers le plafond en gardant l''angle du genou, sans cambrer le dos, puis redescendez avec contrôle.', null),
  ('e7f2efa8-db09-45e8-84e6-9081970b55f5', 'Fire Hydrant', 'À quatre pattes, genou fléchi à angle droit, levez la jambe sur le côté comme une patte de chien, sans faire pivoter le bassin, puis redescendez avec contrôle.', null),
  ('48aa1405-e0ac-42c1-a7ac-1ba17e88a09c', 'Clamshell', 'Allongé sur le côté, genoux fléchis et pieds joints l''un sur l''autre, ouvrez le genou du dessus comme une coquille sans faire rouler le bassin en arrière, puis refermez avec contrôle.', null),
  ('efdfb448-64fc-4503-9078-648e4fe973a5', 'Hip Airplane', 'En équilibre sur une jambe, buste penché en avant, faites pivoter le bassin d''un côté à l''autre en gardant la jambe d''appui stable, bras écartés pour l''équilibre.', null),
  ('ed5283a9-4170-4115-b77d-db0dd086d47a', 'Side-Lying Hip Abduction', 'Allongé sur le côté, jambe du dessous légèrement fléchie, levez la jambe du dessus tendue vers le plafond sans faire rouler le bassin en arrière, puis redescendez avec contrôle.', null),
  ('5127c823-2437-4d1a-b496-98de6fc56c89', 'Side-Lying Leg Raise', 'Allongé sur le côté, jambe du dessous légèrement fléchie, levez la jambe du dessus tendue vers le plafond sans faire rouler le bassin en arrière, puis redescendez avec contrôle.', null),
  ('c2ac1a0b-4627-4705-9829-44a11c13b8c1', 'Lying Hamstring Walkout', 'Allongé sur le dos, talons posés au sol, bassin surélevé, faites glisser lentement les talons vers l''extérieur en gardant le bassin haut, puis ramenez-les.', null),
  ('4e0b6060-9975-4bd1-9f5d-ac862f78ad67', 'Towel Hamstring Curl', 'Allongé sur le dos, talons posés sur une serviette ou un ballon, bassin surélevé, fléchissez les genoux pour ramener les talons vers les fesses, puis retendez les jambes avec contrôle.', null),
  ('a98c038c-5b54-45f7-a80d-0d3ec1e99969', 'Stability Ball Hamstring Curl', 'Allongé sur le dos, talons posés sur une serviette ou un ballon, bassin surélevé, fléchissez les genoux pour ramener les talons vers les fesses, puis retendez les jambes avec contrôle.', null),
  ('340dac93-b077-4640-afa4-c2a730991ff7', 'Banded Glute Bridge', 'Élastique positionné juste au-dessus des genoux, allongé sur le dos genoux fléchis, soulevez le bassin en poussant les genoux contre la résistance, puis redescendez avec contrôle.', null),
  ('81fc454c-468d-47b1-919a-bc1fbe5a496a', 'Banded Hip Thrust', 'Élastique positionné juste au-dessus des genoux, allongé sur le dos genoux fléchis, soulevez le bassin en poussant les genoux contre la résistance, puis redescendez avec contrôle.', null),
  ('fbe68d7e-6bf0-4c97-b4c5-1a8a47a20165', 'Banded Frog Pump', 'Élastique positionné juste au-dessus des genoux, allongé sur le dos plantes de pieds jointes, soulevez le bassin en poussant les genoux contre la résistance, puis redescendez.', null),
  ('fef1229f-5858-44b0-a36e-082e05c73aa3', 'Banded Clamshell', 'Élastique positionné juste au-dessus des genoux, allongé sur le côté genoux fléchis, ouvrez le genou du dessus contre la résistance, puis refermez avec contrôle.', null),
  ('a4185d4b-cf20-46e6-b3b4-2b7837999fa4', 'Banded Lateral Walk', 'Élastique positionné aux chevilles ou juste au-dessus des genoux, jambes légèrement fléchies, avancez par petits pas latéraux en maintenant la tension de l''élastique.', null),
  ('6782e9a1-e8c5-4206-8402-3e6b4be1e0c5', 'Banded Monster Walk', 'Élastique positionné aux chevilles, jambes légèrement fléchies, avancez en pas croisés diagonaux en maintenant la tension de l''élastique.', null),
  ('0c253bf0-3b89-49b2-b665-b51c58af4161', 'Banded Squat', 'Élastique positionné juste au-dessus des genoux ou sur les épaules, descendez en fléchissant les hanches et les genoux jusqu''à ce que les cuisses soient parallèles au sol, dos droit, puis remontez.', null),
  ('d1eef68d-4107-4a71-bca0-27373ef4f31f', 'Banded Donkey Kick', 'À quatre pattes, genou fléchi à angle droit, poussez le talon vers le plafond en gardant l''angle du genou, sans cambrer le dos, puis redescendez avec contrôle.', null),
  ('f7185596-418d-4b26-a35b-4169bf169c7e', 'Banded Fire Hydrant', 'Élastique positionné juste au-dessus des genoux, à quatre pattes, levez la jambe sur le côté contre la résistance, puis redescendez avec contrôle.', null),
  ('292c8cb2-1513-4592-ae5f-f8158ab7365d', 'Banded Kickback', 'En appui sur les mains et un genou, poussez l''autre pied vers l''arrière et le haut en contractant le fessier, puis revenez avec contrôle.', null),
  ('82e85e8b-046e-4680-8f6e-e50da1481ad3', 'Banded Standing Hip Abduction', 'Debout, élastique positionné juste au-dessus des chevilles ou des genoux, écartez une jambe sur le côté contre la résistance, puis revenez avec contrôle.', null),
  ('e42d3f76-6b43-453e-8535-1233636fd54e', 'Banded Seated Hip Abduction', 'Assis, élastique positionné juste au-dessus des genoux, écartez les genoux contre la résistance, puis revenez avec contrôle.', null),
  ('a95011da-9360-4b75-b01c-0ace84fff614', 'Band Pull-Apart', 'Debout, élastique tendu devant vous à hauteur de poitrine, bras tendus, écartez les mains sur les côtés en resserrant les omoplates, puis revenez lentement.', null),
  ('d412b4a7-cd7a-4f50-af5b-c73fc85015bb', 'Banded Face Pull', 'Élastique fixé devant vous à hauteur de visage, tirez vers le visage en écartant les mains et en resserrant les omoplates, coudes hauts, puis revenez lentement.', null),
  ('a939a9ca-af72-4a9a-8d12-d4b017a719bd', 'Banded Row', 'Élastique fixé devant vous, assis ou debout, tirez les poignées vers l''abdomen en resserrant les omoplates, puis revenez lentement.', null),
  ('b6b8f64d-913d-460f-8315-c7d791225ef2', 'Banded Lat Pulldown', 'Assis face à la poulie haute, tirez la barre vers le haut de la poitrine en resserrant les omoplates, puis remontez avec contrôle jusqu''à extension des bras.', null),
  ('78b7d15c-09fd-49ad-b4c4-264562a5143b', 'Banded Pallof Press', 'Debout de côté par rapport à la poulie ou l''élastique, poignée tenue devant la poitrine, tendez les bras devant vous en résistant à la rotation du buste, puis ramenez les mains à la poitrine.', null),
  ('603eb836-0ce4-455f-8c4b-019cd7173b66', 'Banded Woodchop', 'Debout de côté par rapport à la poulie ou l''élastique fixé en hauteur, tirez la poignée en diagonale vers la hanche opposée en faisant pivoter le buste, puis revenez avec contrôle.', null),
  ('7d6b6f85-05fe-48de-92a7-81c47abc1101', 'Banded Dead Bug', 'Allongé sur le dos, bras tendus vers le plafond, genoux fléchis à la verticale, descendez lentement un bras et la jambe opposée vers le sol sans décoller le bas du dos, puis revenez et alternez.', null),
  ('36e9c6b7-c248-4d88-b208-4f614f29da6e', 'Hollow Body Hold', 'Allongé sur le dos, bras tendus derrière la tête, jambes tendues et légèrement décollées, bas du dos plaqué au sol, et maintenez la position en forme de banane.', null),
  ('ea3afa82-b6df-47c9-9646-7b6391368dbc', 'Hollow Rock', 'Allongé sur le dos, bras tendus derrière la tête, jambes tendues, bas du dos plaqué au sol, balancez légèrement le corps d''avant en arrière en gardant la position creusée.', null),
  ('f731a916-31f6-476d-8c4b-c9ee5763b152', 'V-Up', 'Allongé sur le dos, bras et jambes tendus, relevez simultanément le buste et les jambes tendues pour toucher les pieds avec les mains, puis redescendez avec contrôle.', null),
  ('54a69cf2-a6b2-4b33-a23c-8ebf2c2f2923', 'Flutter Kick', 'Allongé sur le dos, jambes tendues légèrement décollées du sol, battez des jambes en alternance sur un petit amplitude, bas du dos plaqué au sol.', null),
  ('095ddec9-8ddd-415e-90f9-f2f511c90d3f', 'Lying Leg Raise', 'Allongé sur le dos, jambes tendues, levez-les jusqu''à la verticale en gardant le bas du dos au sol, puis redescendez lentement sans les poser complètement.', null),
  ('72ff039d-5e98-4eaa-b1cf-320ce58d6900', 'Toe Touch', 'Allongé sur le dos, jambes tendues vers le plafond, relevez le buste en tendant les bras vers les pieds, puis redescendez avec contrôle.', null),
  ('19acafe1-94a2-438c-92b8-471fac96e726', 'Heel Tap', 'Allongé sur le dos, jambes fléchies à la verticale, alternez en touchant un talon au sol de chaque côté sans décoller le bas du dos, puis revenez au centre.', null),
  ('4d8b2a01-c8da-4608-bc9e-bda309eb74ab', 'Plank Shoulder Tap', 'En planche haute, mains sous les épaules, touchez alternativement l''épaule opposée avec chaque main sans laisser le bassin osciller.', null),
  ('490f71cf-19a7-487f-b194-7d181cd64ed6', 'Plank Jack', 'En planche haute, écartez puis resserrez les pieds par petits sauts, comme un jumping jack, en gardant le bassin stable et gainé.', null),
  ('0071695b-e6a8-47d4-a8a3-b3e90aba9bcb', 'Bear Plank', 'En appui sur les mains et les pieds, genoux légèrement décollés du sol, dos plat, maintenez la position en gardant les hanches à hauteur des épaules.', null),
  ('5da62b20-5a3f-42d1-b9ca-7f7654d8e58f', 'Bear Crawl', 'À quatre pattes, genoux légèrement décollés du sol, avancez en déplaçant une main et le pied opposé en même temps, dos plat et bassin stable.', null),
  ('4c93055b-6a25-4e02-b2f7-79a4696d696c', 'Crab Walk', 'Assis, mains au sol derrière vous, bassin décollé du sol, avancez en déplaçant une main et le pied opposé en même temps.', null),
  ('847e520c-b1d6-478b-a0b0-eabed259c433', 'Inchworm', 'Debout, penchez le buste en avant pour poser les mains au sol, marchez avec les mains vers l''avant jusqu''à la position de planche, puis marchez avec les pieds vers les mains et redressez-vous.', null),
  ('3e4b8110-48e4-4045-8106-0fe84378b621', 'L-Sit Hold', 'En appui sur les mains, jambes tendues à l''horizontale devant vous, maintenez la position sans plier les genoux ni les hanches.', null),
  ('339f46d1-cd05-4403-9c38-4055a0627d46', 'Seated Knee Tuck', 'Assis, buste légèrement penché en arrière, mains au sol derrière vous, alternez en ramenant les genoux vers la poitrine puis en les tendant, sans poser les pieds.', null),
  ('f12718a1-97d7-4ba2-ab4e-cffbca1e9ad0', 'Side Plank Hip Dip', 'En planche latérale sur l''avant-bras, laissez la hanche descendre doucement vers le sol puis remontez-la, sans laisser le bassin pivoter vers l''avant ou l''arrière.', null),
  ('7a1d935a-feb8-43fc-be7b-461e18fcfbdf', 'Copenhagen Plank', 'En appui sur un avant-bras, jambe du dessus posée sur un banc, jambe du dessous tendue, soulevez le bassin et la jambe du dessous du sol et maintenez la position.', null),
  ('cf94ec59-b654-42e7-997a-f28dac8c18e4', 'Dragon Flag', 'Allongé sur un banc, mains agrippées derrière la tête, corps tendu, soulevez tout le corps en un seul bloc jusqu''à ce que seules les épaules touchent le banc, puis redescendez lentement.', null),
  ('6b1f26fd-130e-4618-a64c-dcf9ed3303dd', 'Burpee', 'Debout, descendez en squat, posez les mains au sol et sautez les pieds en arrière en position de planche, ramenez les pieds vers les mains, puis sautez verticalement bras tendus vers le haut.', null),
  ('0a99434a-ecdf-42ae-b5b2-79b607f21d16', 'Half Burpee', 'Debout, descendez en squat, posez les mains au sol et sautez les pieds en arrière en position de planche, puis ramenez les pieds vers les mains et redressez-vous, sans saut final.', null),
  ('e4082860-ac2e-4282-b8d0-994c6d8abd45', 'Squat Thrust', 'Debout, descendez en squat, posez les mains au sol et sautez les pieds en arrière en position de planche, puis ramenez immédiatement les pieds vers les mains et redressez-vous.', null),
  ('99be8779-0525-4a1d-854d-dbe8d1f08267', 'High Knees', 'Sur place, courez en amenant alternativement chaque genou le plus haut possible vers la poitrine, à un rythme soutenu.', null),
  ('2d64bef7-a8f1-4b59-b798-8c7e052dfee6', 'Jumping Jack', 'Debout, sautez en écartant simultanément les jambes et en levant les bras tendus au-dessus de la tête, puis sautez pour revenir à la position de départ.', null),
  ('858ae748-1158-4544-bdd0-3809c96f1a6e', 'Skater Hop', 'En équilibre sur une jambe, sautez latéralement sur l''autre jambe en amortissant la réception, jambe libre passant derrière, comme un patineur.', null),
  ('e63ff57d-54de-4e1c-bc9b-46bad7dbc555', 'Lateral Shuffle', 'Jambes fléchies, hanches basses, déplacez-vous latéralement par petits pas chassés rapides, sans croiser les pieds.', null),
  ('d78bf2fd-72bb-4477-8697-0af7a4b8f055', 'Fast Feet', 'Sur place, jambes légèrement fléchies, effectuez de très petits pas rapides en alternant les pieds le plus vite possible.', null),
  ('5691ab3c-e6ed-4409-b549-f83ae7e1b882', 'Sprawl', 'Debout, jetez rapidement les mains au sol et les pieds en arrière en position de planche basse, puis ramenez les pieds vers les mains et redressez-vous.', null),
  ('38bcd642-0bc3-4cc9-a70c-795e6a33b8fe', 'Seal Jack', 'Debout, sautez en écartant les jambes tout en ramenant les bras tendus devant la poitrine, puis sautez pour revenir à la position de départ.', null),
  ('af57db77-22a8-42a0-9a73-406e930c0e36', 'Cat-Cow Stretch', 'À quatre pattes, alternez entre creuser le dos en relevant la tête (position vache) et arrondir le dos en rentrant le menton (position chat), au rythme de la respiration.', null),
  ('680ec70b-90e5-401e-a7b1-44a0519d35ab', 'Arm Circles', 'Debout, bras tendus sur les côtés, effectuez de petits cercles avec les bras, d''abord dans un sens puis dans l''autre.', null),
  ('3d6693f6-a61c-46df-aa22-c44fa25d35db', 'World''s Greatest Stretch', 'En fente avant, posez la main opposée au sol à l''intérieur du pied avant, puis faites pivoter le buste et le bras libre vers le plafond en ouvrant la cage thoracique.', null),
  ('a1cef35b-9f88-4b6a-9acd-2b9ab5177339', 'Leg Swings', 'En vous tenant à un appui, balancez une jambe tendue d''avant en arrière, puis latéralement, en augmentant progressivement l''amplitude.', null),
  ('7b84f0f5-dfc4-4ea2-a8bb-34aeca21b6f7', 'Torso Twists', 'Debout, pieds ancrés au sol, faites pivoter doucement le buste d''un côté puis de l''autre en gardant le bassin face à l''avant.', null),
  ('53e61d8d-450a-4344-84db-c3773363f23b', 'Doorway Chest Stretch', 'Debout dans l''encadrement d''une porte, avant-bras contre le chambranle, avancez légèrement le corps vers l''avant jusqu''à sentir l''étirement de la poitrine, et maintenez la position.', null),
  ('edc36ea0-0f19-4635-beca-11f41cdb9e6f', 'Child''s Pose', 'Assis sur les talons, penchez le buste vers l''avant, bras tendus devant vous au sol, front posé au sol, et maintenez la position en respirant calmement.', null),
  ('b05f9018-bb26-443e-9a16-ec9d9e7eff54', 'Kneeling Hip Flexor Stretch', 'En fente basse, genou arrière au sol, poussez légèrement le bassin vers l''avant jusqu''à sentir l''étirement à l''avant de la hanche arrière, et maintenez la position.', null),
  ('61bbbd24-b9f3-4c74-bda9-6e91af7fa279', 'Hamstring Stretch', 'Assis ou debout, jambe tendue devant vous, penchez le buste vers l''avant en gardant le dos droit jusqu''à sentir l''étirement à l''arrière de la cuisse, et maintenez la position.', null),
  ('2445312f-705d-4190-9bcb-38ebb00d1f24', 'Standing Quad Stretch', 'Debout, en équilibre sur une jambe, attrapez l''autre cheville derrière vous et ramenez le talon vers la fesse jusqu''à sentir l''étirement à l''avant de la cuisse, et maintenez la position.', null),
  ('31bd9c62-b8c5-484f-8d9c-6cfaa1bb74cd', 'Seated Forward Fold', 'Assis, jambes tendues devant vous, penchez le buste vers l''avant en gardant le dos droit jusqu''à sentir l''étirement à l''arrière des cuisses, et maintenez la position.', null),
  ('fd622b97-312e-4843-bf5f-a2382af8709f', 'Cross-Body Shoulder Stretch', 'Debout, amenez un bras tendu devant la poitrine et maintenez-le avec l''autre bras jusqu''à sentir l''étirement de l''épaule, et maintenez la position.', null),
  ('49e7aee4-551a-4504-b225-dd09a19e0741', 'Wall Calf Stretch', 'Debout face à un mur, une jambe reculée et tendue, talon au sol, penchez-vous vers le mur jusqu''à sentir l''étirement du mollet arrière, et maintenez la position.', null),
  ('ac2c80fd-f612-4fe9-80c9-48b22823ff3d', 'Butterfly Stretch', 'Assis, plantes de pieds jointes, genoux ouverts vers l''extérieur, penchez légèrement le buste vers l''avant jusqu''à sentir l''étirement à l''intérieur des cuisses, et maintenez la position.', null);
